<section class="faq-section sec-padd2">

    <div class="container">
        
        <div class="row">
            
            <div class="col-md-12 col-sm-12 col-xs-12">
                      

                        <div class="accordion-box style-one">
                            <!--Start single accordion box-->


                            <div class="accordion animated out" data-animation="fadeInUp" data-delay="0">
                                <div class="acc-btn">
                                    <p class="title">लोकमंगल फाऊंडेशन कोणासाठी काम करते?</p>


                                    <div class="toggle-icon">
                                        <span class="plus fa fa-arrow-circle-o-right"></span><span class="minus fa fa-arrow-circle-o-down"></span>
                                    </div>
                                </div>


                                <div class="acc-content">
                                    <div class="text">
                                        <p>लोकमंगल फाउंडेशन ग्रामीण भागातील लोकांसाठी काम करते. आम्ही ग्रामीण समाजाच्या उन्नतीसाठी काम करतो.</p>
                                    </div>
                                </div>
                            </div>
                            <!--Start single accordion box-->


                            <div class="accordion animated out" data-animation="fadeInUp" data-delay="0">
                                <div class="acc-btn active">
                                    <p class="title">आम्ही कशाप्रकारे मदत करू शकतो?</p>

                                    <div class="toggle-icon">
                                        <i class="plus fa fa-arrow-circle-o-right"></i><i class="minus fa fa-arrow-circle-o-down"></i>
                                    </div>
                                </div>


                                <div class="acc-content collapsed">
                                    <div class="text">
                                        <p>आपल्या सर्व प्रकारच्या मदतीचे येथे स्वागत आहे. लोकमंगल फाउंडेशनच्या कार्यात सहभागी होण्यासाठी आपण स्वयंसेवक म्हणून आपला वेळ देऊ शकता, आर्थिक अथवा वस्तूंच्या स्वरुपात मदत देऊ शकता, एखाद्या विद्यार्थ्याची जबाबदारी घेऊ शकता अथवा आपल्या समाजामधून निधी उभारू शकता.</p>
                                    </div>
                                </div>
                            </div>
                            <!--Start single accordion box-->


                            <div class="accordion animated out" data-animation="fadeInUp" data-delay="0">
                                <div class="acc-btn">
                                    <p class="title">मला एखाद्या मुलाची जबाबदारी घेता येऊ शकते का?</p>


                                    <div class="toggle-icon">
                                        <i class="plus fa fa-arrow-circle-o-right"></i><i class="minus fa fa-arrow-circle-o-down"></i>
                                    </div>
                                </div>


                                <div class="acc-content">
                                    <div class="text">
                                        <p>होय, तुम्ही लोकमंगल फाऊंडेशनमध्ये विद्यार्थ्यांना प्रायोजित करू शकता.</p>
                                    </div>
                                </div>
                            </div>
                            <!--Start single accordion box-->


                            <div class="accordion animated out" data-animation="fadeInUp" data-delay="0">
                                <div class="acc-btn">
                                    <p class="title">माझी देणगी कर सवलतीस पात्र आहे का?</p>


                                    <div class="toggle-icon">
                                        <i class="plus fa fa-arrow-circle-o-right"></i><i class="minus fa fa-arrow-circle-o-down"></i>
                                    </div>
                                </div>


                                <div class="acc-content">
                                    <div class="text">
                                        <p>होय, आम्ही एक नोंदणीकृत चॅरिटेबल ट्रस्ट आहोत. आयकर अधिनियम, १९६१च्या कलम ८० जी अंतर्गत आपल्या देणग्या कर सवलतीस पूर्णपणे पात्र आहेत.</p>
                                    </div>
                                </div>
                            </div>

                            <div class="accordion animated out" data-animation="fadeInUp" data-delay="0">
                                <div class="acc-btn">
                                    <p class="title">मला आपल्याशी कशाप्रकारे संपर्क साधता येईल? </p>


                                    <div class="toggle-icon">
                                        <i class="plus fa fa-arrow-circle-o-right"></i><i class="minus fa fa-arrow-circle-o-down"></i>
                                    </div>
                                </div>


                                <div class="acc-content">
                                    <div class="text">
                                        <p>या माहितीसाठी कृपया आमचे संपर्क पृष्ठ पहा.</p>
                                    </div>
                                </div>
                            </div>

                            <div class="accordion animated out" data-animation="fadeInUp" data-delay="0">
                                <div class="acc-btn">
                                    <p class="title">तुमचे प्रकल्प महाराष्ट्राव्यतिरिक्त इतर राज्यांना लागू आहेत का?</p>


                                    <div class="toggle-icon">
                                        <i class="plus fa fa-arrow-circle-o-right"></i><i class="minus fa fa-arrow-circle-o-down"></i>
                                    </div>
                                </div>


                                <div class="acc-content">
                                    <div class="text">
                                        <p>होय, आम्ही इतर राज्यांमधील ग्रामीण समाजांसाठी देखील काम करू इच्छितो.</p>
                                    </div>
                                </div>
                            </div>

                            <div class="accordion animated out" data-animation="fadeInUp" data-delay="0">
                                <div class="acc-btn">
                                    <p class="title">परदेशी नागरिकांना ऑनलाईन देणगी देता येईल का?</p>


                                    <div class="toggle-icon">
                                        <i class="plus fa fa-arrow-circle-o-right"></i><i class="minus fa fa-arrow-circle-o-down"></i>
                                    </div>
                                </div>


                                <div class="acc-content">
                                    <div class="text">
                                        <p>होय, अधिक माहितीसाठी कृपया देणगी च्या पृष्ठाला भेट द्या.</p>
                                    </div>
                                </div>
                            </div>

                            <div class="accordion animated out" data-animation="fadeInUp" data-delay="0">
                                <div class="acc-btn">
                                    <p class="title">माझ्या देणगीचा वापर कोठे केला जाईल?</p>


                                    <div class="toggle-icon">
                                        <i class="plus fa fa-arrow-circle-o-right"></i><i class="minus fa fa-arrow-circle-o-down"></i>
                                    </div>
                                </div>


                                <div class="acc-content">
                                    <div class="text">
                                        <p>आपल्या देणगीचा विनियोग आमच्या चार प्रकल्पांपैकी आवश्यकता असेल त्या प्रकल्पासाठी केला जाईल. आपण कोणत्याही विशिष्ट प्रकल्पासाठी देणगी देऊ इच्छित असल्यास, आम्हाला सूचित करू शकता जेणेकरून आपल्या देणगीचा विनियोग त्या प्रकल्पासाठीच केला जाईल. </p>
                                    </div>
                                </div>
                            </div>

                            <div class="accordion animated out" data-animation="fadeInUp" data-delay="0">
                                <div class="acc-btn">
                                    <p class="title">मी लोकमंगल फाऊंडेशनला मदत का करावी?</p>


                                    <div class="toggle-icon">
                                        <i class="plus fa fa-arrow-circle-o-right"></i><i class="minus fa fa-arrow-circle-o-down"></i>
                                    </div>
                                </div>


                                <div class="acc-content">
                                    <div class="text">
                                        <p>लोकमंगल फाऊंडेशन ग्रामीण समाजाच्या उन्नतीसाठी काम करते. त्यांचे जीवनमान उंचावण्यासाठी आम्ही सर्वतोपरी कार्यरत आहोत. जर आपणास असे वाटत असेल की या समाजानेही काळासोबत पुढे जावे, तर आपणही आमच्याबरोबर सहभागी व्हा. </p>
                                    </div>
                                </div>
                            </div>

                            <div class="accordion animated out" data-animation="fadeInUp" data-delay="0">
                                <div class="acc-btn">
                                    <p class="title">लोकमंगल फाऊंडेशन फक्त ग्रामीण समाजासाठीच का काम करते?</p>


                                    <div class="toggle-icon">
                                        <i class="plus fa fa-arrow-circle-o-right"></i><i class="minus fa fa-arrow-circle-o-down"></i>
                                    </div>
                                </div>


                                <div class="acc-content">
                                    <div class="text">
                                        <p>ग्रामीण भागातील जनतेला बहुतेक वेळा आर्थिक कमतरतेला तोंड द्यावे लागते तसेच या भागात आधुनिक सोयी सुविधांचाही अभाव असतो. आर्थिक कमतरतेमुळे त्यांच्यावर पडणारा भार हलका करण्याचा प्रयत्न लोकमंगल फाऊंडेशन आपल्या प्रकल्पांद्वारे करीत आहे. तसेच त्यांना विकासाच्या प्रवाहात आणण्यासाठी प्रयास करीत आहे.</p>
                                    </div>
                                </div>
                            </div>

                        </div>

